187: /** In-memory rate limiter (per-isolate, resets on cold start) with auto-cleanup */
188: const rateLimitMap = new Map<string, { count: number; resetAt: number }>();
189: let lastCleanup = Date.now();
190: 
191: function cleanupRateLimitMap() {
192:   const now = Date.now();
193:   if (now - lastCleanup < 60_000) return;
194:   lastCleanup = now;
195:   for (const [key, entry] of rateLimitMap) {
196:     if (now > entry.resetAt) rateLimitMap.delete(key);
197:   }
198: }
199: 
200: export function checkRateLimit(
201:   key: string,
202:   maxRequests = 30,
203:   windowMs = 60_000
204: ): { allowed: boolean; remaining: number } {
205:   cleanupRateLimitMap();
206:   const now = Date.now();
207:   const entry = rateLimitMap.get(key);
208: 
209:   if (!entry || now > entry.resetAt) {
210:     rateLimitMap.set(key, { count: 1, resetAt: now + windowMs });
211:     return { allowed: true, remaining: maxRequests - 1 };
212:   }
213: 
214:   entry.count++;
215:   const remaining = Math.max(0, maxRequests - entry.count);
216:   return { allowed: entry.count <= maxRequests, remaining };
217: }
