52: export function measure(distDir, html) {
53:   const assets = extractInitialAssets(html);
54:   const resolve = (href) => path.join(distDir, href.replace(/^\//u, ""));
55:   const size = (list) => list.map((href) => {
56:     const file = resolve(href);
57:     if (!existsSync(file)) throw new Error(`asset referenciado no index.html nao existe: ${href}`);
58:     return { href, kb: gzipKB(readFileSync(file)) };
59:   });
60:   const js = size(assets.js);
61:   const css = size(assets.css);
62:   const sum = (items) => items.reduce((total, item) => total + item.kb, 0);
63:   const allAssets = allAssetFiles(distDir).map(({ file, href }) => ({
64:     href,
65:     gzipKB: gzipKB(readFileSync(file)),
66:   }));
67:   // Diferentemente de initial-js, este limite tambem cobre chunks lazy. Eles
68:   // afetam diretamente a latencia percebida na primeira navegacao daquela rota.
69:   const largestChunkKB = allAssets
70:     .filter(({ href }) => href.endsWith(".js"))
71:     .reduce((largest, item) => Math.max(largest, item.gzipKB), 0);
72:   const totalAssetsKB = allAssets.reduce((total, item) => total + item.gzipKB, 0);
73:   return {
74:     js,
75:     css,
76:     jsKB: sum(js),
77:     cssKB: sum(css),
78:     largestChunkKB,
79:     totalAssetsKB,
80:   };
81: }
